import { test } from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, listCustomers, validateCustomer, normalizeId } from '../src/customers.js';

test('getCustomer finds a customer by id', () => {
  const r = getCustomer('C-003');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Kite & Co');
});

test('getCustomer reports an unknown id', () => {
  assert.deepEqual(getCustomer('C-999'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('every customer has a tier', () => {
  for (const c of listCustomers()) assert.ok(['gold', 'silver', 'standard'].includes(c.tier), c.id);
});

test('validateCustomer needs an id, a name and an email', () => {
  assert.equal(validateCustomer({ id: 'C-100', name: 'X', email: 'x@y.example' }).ok, true);
  assert.deepEqual(validateCustomer({ id: 'C-100', name: 'X', email: 'nope' }), { ok: false, error: 'CUSTOMER_INVALID' });
});

test('normalizeId: trims whitespace from ID', () => {
  assert.equal(normalizeId(' C-001 '), 'C-001');
  assert.equal(normalizeId('  C-005  '), 'C-005');
});

test('normalizeId: converts lowercase to uppercase', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId('c-007'), 'C-007');
});

test('normalizeId: handles mixed case and spaces', () => {
  assert.equal(normalizeId(' c-001 '), 'C-001');
  assert.equal(normalizeId('C-007 '), 'C-007');
  assert.equal(normalizeId(' c-007'), 'C-007');
});

test('normalizeId: handles already-normalized IDs', () => {
  assert.equal(normalizeId('C-001'), 'C-001');
  assert.equal(normalizeId('C-012'), 'C-012');
});

test('normalizeId: works with non-string input', () => {
  assert.equal(normalizeId(123), '123');
});

test('getCustomer: finds customer with lowercase ID', () => {
  const result = getCustomer('c-001');

  assert.equal(result.ok, true);
  assert.equal(result.value.name, 'Northwind Studio');
});

test('getCustomer: finds customer with mixed case and spaces', () => {
  const result = getCustomer(' c-002 ');

  assert.equal(result.ok, true);
  assert.equal(result.value.name, 'Blue Fern Bakery');
});

test('getCustomer: finds customer with uppercase and spaces', () => {
  const result = getCustomer(' C-003 ');

  assert.equal(result.ok, true);
  assert.equal(result.value.name, 'Kite & Co');
});

test('getCustomer: still reports unknown customer correctly', () => {
  const result = getCustomer('c-999');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('getCustomer: normalizes various formats consistently', () => {
  const variants = ['C-005', 'c-005', ' C-005 ', ' c-005 '];
  const expected = { ok: true, value: { id: 'C-005', name: 'Orchard Health', email: 'billing@orchard.example', country: 'DE', tier: 'silver' } };

  for (const variant of variants) {
    const result = getCustomer(variant);
    assert.equal(result.ok, expected.ok);
    assert.equal(result.value.id, expected.value.id);
    assert.equal(result.value.name, expected.value.name);
  }
});

